using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is required");
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        IChatClient chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Path.GetTempPath(), "MyApp.Evals"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        ChatResponse response = await run.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result!;
        AssertScoreMeetsThreshold(result, CoherenceEvaluator.CoherenceMetricName, 3);
        AssertScoreMeetsThreshold(result, RelevanceEvaluator.RelevanceMetricName, 3);
        AssertScoreMeetsThreshold(result, FluencyEvaluator.FluencyMetricName, 3);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(FactualQuestion_IsGroundedAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await run.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result!;
        AssertScoreMeetsThreshold(result, RelevanceEvaluator.RelevanceMetricName, 4);
        AssertScoreMeetsThreshold(result, GroundednessEvaluator.GroundednessMetricName, 4);
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsCoherence()
    {
        await using ScenarioRun run =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(MultiTurnConversation_MaintainsCoherence));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to plan a trip to Japan.")
        };

        ChatResponse response1 = await run.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What about the best time to visit?"));

        ChatResponse response2 = await run.ChatConfiguration!.ChatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await run.EvaluateAsync(messages);

        EvaluationResult result = run.Result!;
        AssertScoreMeetsThreshold(result, CoherenceEvaluator.CoherenceMetricName, 4);
        AssertScoreMeetsThreshold(result, RelevanceEvaluator.RelevanceMetricName, 3);
    }

    private static void AssertScoreMeetsThreshold(
        EvaluationResult result, string metricName, int threshold)
    {
        EvaluationMetric metric = result[metricName];
        Assert.IsNotNull(metric.NumericValue, $"{metricName} should have a numeric score");
        Assert.IsTrue(
            metric.NumericValue >= threshold,
            $"{metricName} score {metric.NumericValue} is below threshold {threshold}");
    }
}

